+     * Validation happens on Send only, with our own messages, so the fields
+     * must not validate themselves; and every edit re-enables Send.
+     */
+    private <C extends TextFieldBase<C, String>> void configure(C field) {
+        field.setManualValidation(true);
+        field.setValueChangeMode(ValueChangeMode.EAGER);
+        field.addValueChangeListener(event -> onEdit());
+    }
+
+    private void onEdit() {
+        if (!clearing) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void trySend() {
+        if (!send.isEnabled()) {
+            // Nothing to send right after a successful send.
+            return;
+        }
+        if (!validate()) {
+            // Everything the user typed stays put.
+            return;
+        }
+        store.add(new Message(value(name), value(email), value(phone),
+                value(message)));
+        refreshMessages();
+        clearForm();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    /**
+     * Marks every field that breaks a rule invalid and returns whether the form
+     * as a whole may be sent.
+     */
+    private boolean validate() {
+        clearErrors();
+
+        boolean valid = true;
+
+        if (value(name).isBlank()) {
+            setError(name, "Name is required");
+            valid = false;
+        }
+
+        String mail = value(email);
+        String tel = value(phone);
+        if (!mail.isEmpty() && !EMAIL.matcher(mail).matches()) {
+            setError(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (mail.isEmpty() && tel.isEmpty()) {
+            setError(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        String text = value(message);
+        if (text.isBlank()) {
+            setError(message, "Message is required");
+            valid = false;
+        } else if (text.length() > MAX_MESSAGE_LENGTH) {
+            setError(message,
+                    "Message must be at most " + MAX_MESSAGE_LENGTH
+                            + " characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void setError(HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearErrors() {
+        for (HasValidation field : List.<HasValidation> of(name, email, phone,
+                message)) {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        }
+    }
+
+    private void clearForm() {
+        clearing = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+            clearErrors();
+        } finally {
+            clearing = false;
+        }
+    }
+
+    private void refreshMessages() {
+        sentMessages.setItems(store.getMessages());
+    }
+
+    private static String value(HasValue<?, String> field) {
+        String value = field.getValue();
+        return value == null ? "" : value.trim();
+    }
+
+    /** True when the form holds something the user would not want to lose. */
+    private boolean hasInput() {
+        return !raw(name).isEmpty() || !raw(email).isEmpty()
+                || !raw(phone).isEmpty() || !raw(message).isEmpty();
+    }
+
+    private static String raw(HasValue<?, String> field) {
+        String value = field.getValue();
+        return value == null ? "" : value;
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasInput()) {
+            // Nothing to lose, so leaving is not interrupted.
+            return;
+        }
+        if (leaveDialog != null && leaveDialog.isOpened()) {
+            return;
+        }
+        ContinueNavigationAction action = event.postpone();
+        leaveDialog = createLeaveDialog(action);
+        leaveDialog.open();
+    }
+
+    private Dialog createLeaveDialog(ContinueNavigationAction action) {
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+
+        Button keepEditing = new Button("Keep editing", event -> {
+            dialog.close();
+            action.cancel();
+        });
+        Button discard = new Button("Discard", event -> {
+            dialog.close();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR);
+
+        dialog.add(new VerticalLayout(
+                new Span("You have not sent your message yet."),
+                new HorizontalLayout(keepEditing, discard)));
+        return dialog;
+    }
+}
