+package com.example.contact;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+
+    @BeforeEach
+    void openContactView() {
+        navigate(ContactView.class);
+        lookUpFields();
+    }
+
+    private void lookUpFields() {
+        name = $(TextField.class).withLabel("Name").single();
+        email = $(EmailField.class).withLabel("Email").single();
+        phone = $(TextField.class).withLabel("Phone").single();
+        message = $(TextArea.class).withLabel("Message").single();
+        send = $(Button.class).withText("Send").single();
+    }
+
+    private Grid<?> grid() {
+        return $(Grid.class).single();
+    }
+
+    private void fillValidForm() {
+        test(name).setValue("Ada");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("Hello there");
+    }
+
+    @Test
+    void view_hasHeadingLinkFormAndGrid() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertTrue($(RouterLink.class).withText("About").exists());
+        assertTrue(name.isEmpty() && email.isEmpty() && phone.isEmpty()
+                && message.isEmpty());
+        assertTrue(test(send).isUsable(), "Send should be enabled initially");
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void emptyForm_send_reportsEveryFailingRule() {
+        test(send).click();
+
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(name.isInvalid());
+        assertEquals("Give an e-mail address or a phone number",
+                email.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertTrue(message.isInvalid());
+
+        assertFalse($(Notification.class).exists());
+        assertEquals(0, test(grid()).size());
+        assertTrue(test(send).isUsable(), "Send stays enabled after failure");
+    }
+
+    @Test
+    void invalidEmail_isReported_andInputIsKept() {
+        test(name).setValue("Ada");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello");
+
+        test(send).click();
+
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertFalse(name.isInvalid());
+        assertFalse(message.isInvalid());
+        assertEquals("Ada", name.getValue());
+        assertEquals("not-an-email", email.getValue());
+        assertEquals("Hello", message.getValue());
+        assertEquals(0, test(grid()).size());
+    }
+
+    @Test
+    void phoneAlone_isEnough() {
+        test(name).setValue("Ada");
+        test(phone).setValue("+358 40 123 4567");
+        test(message).setValue("Call me");
+
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void tooLongMessage_isReported() {
+        test(name).setValue("Ada");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("x".repeat(501));
+
+        test(send).click();
+
+        assertEquals("Message must be at most 500 characters",
+                message.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals(0, test(grid()).size());
+
+        test(message).setValue("x".repeat(500));
+        test(send).click();
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void validForm_send_notifiesClearsAndDisablesSend() {
+        fillValidForm();
+
+        test(send).click();
+
+        assertTrue(test($(Notification.class).first()).getText()
+                .contains("Message sent"));
+        assertEquals(1, test(grid()).size());
+        assertEquals(new Message("Ada", "ada@example.com", "", "Hello there"),
+                test(grid()).getRow(0));
+        assertTrue(name.isEmpty() && email.isEmpty() && phone.isEmpty()
+                && message.isEmpty());
+        assertFalse(test(send).isUsable(), "Send is disabled after sending");
+
+        test(name).setValue("Grace");
+        assertTrue(test(send).isUsable(), "Editing re-enables Send");
+    }
+
+    @Test
+    void enterKey_sendsTheMessage() {
+        fillValidForm();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void newestMessageIsFirst_andSurvivesLeavingTheView() {
+        fillValidForm();
+        test(send).click();
+        test(name).setValue("Grace");
+        test(email).setValue("grace@example.com");
+        test(message).setValue("Second");
+        test(send).click();
+
+        assertEquals("Grace", test(grid()).getCellText(0, 0));
+        assertEquals("Second", test(grid()).getCellText(0, 1));
+        assertEquals("Ada", test(grid()).getCellText(1, 0));
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+        lookUpFields();
+
+        assertEquals(2, test(grid()).size());
+        assertEquals("Grace", test(grid()).getCellText(0, 0));
+    }
+
+    @Test
+    void emptyForm_leavingIsNotInterrupted() {
+        navigate(AboutView.class);
+
+        assertFalse($(Dialog.class).exists());
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+
+    @Test
+    void filledForm_keepEditing_staysOnTheView() {
+        test(name).setValue("Ada");
+
+        // Postponed, so the navigation does not land on the about view yet.
+        UI.getCurrent().navigate(AboutView.class);
+
+        assertTrue($(Dialog.class).exists());
+        $(Button.class).withText("Keep editing").single().click();
+
+        assertFalse($(Dialog.class).exists(), "The dialog is closed");
+        assertTrue(getCurrentView() instanceof ContactView);
+        assertEquals("Ada", name.getValue());
+    }
+
+    @Test
+    void filledForm_discard_navigates() {
+        test(message).setValue("Half written");
+
+        UI.getCurrent().navigate(AboutView.class);
+        assertTrue(getCurrentView() instanceof ContactView);
+        $(Button.class).withText("Discard").single().click();
+
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+
+    @Test
+    void aboutLink_asksBeforeLeavingWithInput() {
+        test(phone).setValue("123");
+
+        test($(RouterLink.class).withText("About").single()).click();
+
+        assertTrue($(Dialog.class).exists());
+        $(Button.class).withText("Discard").single().click();
+        assertTrue(getCurrentView() instanceof AboutView);
+        assertEquals("About", $(H1.class).single().getText());
+    }
+}
